1: function [cp,enthalpy,standardEntropy] = airThermalProperties(T)
2: %AIRTHERMALPROPERTIES 干空气温度相关的定压比热、质量比焓和标准熵。
3: % 模块作用：用 N2/O2 的 NASA 七系数多项式及 Ar 单原子气体近似，
4: % 按固定质量分数混合。焓/熵的零点任意，只用差值求换热和激波。
5: % 适用 80~2500 K；150~200 K 为 NASA7 低温多项式的少量外推。
6: % 80~150 K 采用在 150 K 连续衔接的振动冻结定比热近似：
7: % h=h150+cp150*(T-150)，s=s150+cp150*ln(T/150)。在此区间
8: % N2/O2 转动自由度仍充分激发，振动自由度基本冻结。此近似仅适用
9: % 稀薄且保持气相的固定组分空气；低于 80 K 或高于 2500 K 返回 NaN。
10: % 系数取 NASA/Glenn 常用的 200~1000 与 1000~6000 K 区间形式。
11: 
12: %% 1. 校验温度并预留输出；已有无解面元的 NaN 原样传递
13: validateattributes(T,{'numeric'},{'real'});
14: T=double(T);
15: cp=nan(size(T)); enthalpy=cp; standardEntropy=cp;
16: valid=isfinite(T) & T>=150 & T<=2500;
17: belowAnchor=isfinite(T) & T>=80 & T<150;
18: if ~any(valid(:)) && ~any(belowAnchor(:)), return; end
19: if any(valid(:))
20: tOriginal=T(valid);
21: t=tOriginal(:);
22: 
23: %% 2. 分别求 N2、O2、Ar，再按干空气质量分数混合
24: R=8.31446261815324;
25: mass=[0.755 0.232 0.013];
26: mass=mass/sum(mass);
27: molecularMass=[0.0280134 0.0319988 0.039948];
28: low=[3.53100528 -1.23660987e-4 -5.02999433e-7 2.43530612e-9 -1.40881235e-12 -1046.97628 2.96747468; ...
29:      3.78245636 -2.99673416e-3  9.84730201e-6 -9.68129509e-9  3.24372837e-12 -1063.94356 3.65767573; ...
30:      2.5         0               0              0              0              0           0];
31: high=[2.95257626 1.39690040e-3 -4.92631603e-7 7.86010367e-11 -4.60755321e-15 -923.948688 5.87188762; ...
32:       3.28253784 1.48308754e-3 -7.57966669e-7 2.09470555e-10 -2.16717794e-14 -1088.45772 5.45323129; ...
33:       2.5        0              0              0              0               0           0];
34: sumCp=zeros(size(t)); sumH=sumCp; sumS=sumCp;
35: for gas=1:3
36:     a=repmat(low(gas,:),numel(t),1);
37:     a(t>=1000,:)=repmat(high(gas,:),nnz(t>=1000),1);
38:     cpOverR=a(:,1)+a(:,2).*t+a(:,3).*t.^2+ ...
39:         a(:,4).*t.^3+a(:,5).*t.^4;
40:     hOverRT=a(:,1)+a(:,2).*t/2+a(:,3).*t.^2/3+ ...
41:         a(:,4).*t.^3/4+a(:,5).*t.^4/5+a(:,6)./t;
42:     sOverR=a(:,1).*log(t)+a(:,2).*t+a(:,3).*t.^2/2+ ...
43:         a(:,4).*t.^3/3+a(:,5).*t.^4/4+a(:,7);
44:     factor=mass(gas)*R/molecularMass(gas);
45:     sumCp=sumCp+factor*cpOverR;
46:     sumH=sumH+factor*t.*hOverRT;
47:     sumS=sumS+factor*sOverR;
48: end
49: cp(valid)=reshape(sumCp,size(tOriginal));
50: enthalpy(valid)=reshape(sumH,size(tOriginal));
51: standardEntropy(valid)=reshape(sumS,size(tOriginal));
52: end
53: 
54: %% 3. 低温振动冻结近似；从 150 K 锚点积分焓和熵，保证连续
55: if any(belowAnchor(:))
56:     [cp150,h150,s150]=airThermalProperties(150);
57:     cp(belowAnchor)=cp150;
58:     enthalpy(belowAnchor)=h150+cp150*(T(belowAnchor)-150);
